7	/**
8	 * Derives an owner's membership points and numeric membership level from their persisted fields.
9	 *
10	 * <p>Points start at 0; add 2 when an email is present; add 1 when {@code namesakeCount} is 0; add
11	 * 2 for a household of 3 or more; add 3 for tenure of at least one elapsed fiscal year. Tenure is
12	 * the number of whole fiscal years (starting 1 July) from the registration date to today, so a
13	 * newly created owner has zero tenure and never earns the tenure points: a fresh owner tops out at
14	 * 5 points.
15	 *
16	 * <p>The membership level maps the points: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
17	 *
18	 * <p>Kept as a standalone class (not a method on {@link OwnerMapper}) so MapStruct does not
19	 * mistake it for an implicit mapping method. Single source of truth so the response DTO and
20	 * the create audit line agree on the points and level.
21	 */
22	public final class MembershipLevel {
23	
24	    private MembershipLevel() {
25	    }
26	
27	    /** The membership points for {@code owner}. */
28	    public static int points(Owner owner) {
29	        int points = 0;
30	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
31	            points += 2;
32	        }
33	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
34	            points += 1;
35	        }
36	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
37	            points += 2;
38	        }
39	        if (owner.getRegistrationDate() != null
40	                && FiscalYear.elapsed(owner.getRegistrationDate(), LocalDate.now()) >= 1) {
41	            points += 3;
42	        }
43	        return points;
44	    }
45	
46	    /** The membership level (1 to 4) for {@code owner}, derived from {@link #points(Owner)}. */
47	    public static int of(Owner owner) {
48	        int points = points(owner);
49	        if (points <= 1) {
50	            return 1;
51	        }
52	        if (points <= 3) {
53	            return 2;
54	        }
55	        if (points <= 5) {
56	            return 3;
57	        }
58	        return 4;
59	    }
60	}
